'use strict';
const useCasesStyle=document.createElement('link');useCasesStyle.rel='stylesheet';useCasesStyle.href='../use-cases.css';document.head.append(useCasesStyle);
const platformStyle=document.createElement('link');platformStyle.rel='stylesheet';platformStyle.href='../platform-sections.css';document.head.append(platformStyle);
const PALACES=[['Da An','Great Peace','Stability, protection and a steady foundation.'],['Liu Lian','Lingering','Delay, repetition and unresolved details.'],['Su Xi','Swift Joy','News, movement and a short window for action.'],['Chi Kou','Red Mouth','Conflict, sharp words and unclear responsibility.'],['Xiao Ji','Small Fortune','Support, cooperation and gradual progress.'],['Kong Wang','Emptiness','Missing information, uncertainty and assumptions that need checking.']];
const CATEGORY_NAMES={work:'Career & job',cooperation:'Business & projects',relationship:'Love & relationships',finance:'Money & cash flow',study:'Study & exams',health:'Health & wellbeing',travel:'Travel & plans',lost:'Lost item',general:'General decision'};
const RULES={lost:['lost','missing','where is','cannot find','can’t find','stolen','phone','wallet','keys','ring','passport'],work:['job','career','interview','offer','promotion','salary','resign','workplace','hiring'],cooperation:['business','project','launch','client','contract','deal','partner','payment','delivery','startup'],relationship:['love','relationship','dating','partner','ex','marriage','breakup','reconcile','friendship'],finance:['money','finance','income','investment','stock','loan','debt','cash','profit','repay'],study:['exam','study','school','course','grade','admission','university','test'],health:['health','symptom','pain','ill','sick','doctor','medicine','surgery','pregnant','recovery'],travel:['travel','trip','flight','train','visa','hotel','journey','move abroad']};
const CLARIFY={work:'What stage are you at, and what concrete feedback have you received?',cooperation:'What stage is the project at, what is blocking it, and when must it launch?',relationship:'What is the current relationship status and the last concrete interaction?',finance:'What amount, deadline, written commitment and maximum loss are involved?',study:'When is the exam, what is your current score and weakest subject?',health:'How long has this lasted, is it worsening, and have you sought medical care?',travel:'When are you leaving and which bookings or documents are confirmed?',lost:'Where and when did you last see it, and where did you go afterward?',general:'What is the current stage, main obstacle, desired date and unacceptable downside?'};
const $=id=>document.getElementById(id),escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let lastReading=null;
function classify(text,selected){if(selected!=='auto')return selected;const q=text.toLowerCase(),scores={};for(const [c,words] of Object.entries(RULES))scores[c]=words.reduce((n,w)=>{const escaped=w.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),matched=new RegExp(`\\b${escaped}\\b`,'i').test(q);return n+(matched?w.length:0)},0);const best=Object.entries(scores).sort((a,b)=>b[1]-a[1])[0];return best&&best[1]>0?best[0]:'general'}
function lunar(date){const parts=new Intl.DateTimeFormat('en-US-u-ca-chinese',{timeZone:'Asia/Shanghai',month:'numeric',day:'numeric'}).formatToParts(date),monthText=parts.find(x=>x.type==='month')?.value||'',month=parseInt(monthText,10),day=Number(parts.find(x=>x.type==='day')?.value);const sp=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(date),o=Object.fromEntries(sp.map(x=>[x.type,x.value]));return{month,day,hour:Number(o.hour),solar:`${o.year}-${o.month}-${o.day} ${o.hour}:${o.minute}`,leap:/bis|leap/i.test(monthText)}}
function calculate(c){const hourIndex=Math.floor((c.hour+1)%24/2),m=(c.month-1)%6,d=(m+c.day-1)%6,t=(d+hourIndex)%6;return{m,d,t,hourIndex}}
function downloadCard(data){const canvas=document.createElement('canvas'),c=canvas.getContext('2d');canvas.width=1080;canvas.height=1350;const grad=c.createLinearGradient(0,0,1080,1350);grad.addColorStop(0,'#fffaf0');grad.addColorStop(1,'#ead8ba');c.fillStyle=grad;c.fillRect(0,0,1080,1350);c.strokeStyle='rgba(145,89,48,.22)';c.lineWidth=2;c.beginPath();c.roundRect(55,55,970,1240,30);c.stroke();c.fillStyle='#a83b2e';c.font='700 42px Georgia';c.fillText('WENSHI · XIAO LIU REN',100,135);c.fillStyle='#806b58';c.font='24px Segoe UI';c.fillText('A six-palace timing reading',100,178);c.textAlign='center';c.fillStyle='#a83b2e';c.font='700 104px Georgia';c.fillText(PALACES[data.p.t][0],540,330);c.fillStyle='#315c50';c.font='700 25px Segoe UI';c.fillText(`${CATEGORY_NAMES[data.record.category]} · ${PALACES[data.p.d][0]} → ${PALACES[data.p.t][0]}`,540,380);c.textAlign='left';function wrap(text,x,y,width,lineHeight,max=8){const words=String(text).split(' '),lines=[];let line='';for(const word of words){const test=line?line+' '+word:word;if(c.measureText(test).width>width&&line){lines.push(line);line=word}else line=test}if(line)lines.push(line);lines.slice(0,max).forEach((l,i)=>c.fillText(l,x,y+i*lineHeight));return y+Math.min(lines.length,max)*lineHeight}c.fillStyle='#8d735d';c.font='700 21px Segoe UI';c.fillText('QUESTION',100,470);c.fillStyle='#302c27';c.font='700 34px Segoe UI';let y=wrap(data.record.question,100,525,880,48,3)+28;c.fillStyle='#315c50';c.beginPath();c.roundRect(90,y,900,145,20);c.fill();c.fillStyle='#ead29d';c.font='700 20px Segoe UI';c.fillText('DIRECT ANSWER',125,y+42);c.fillStyle='#fffaf0';c.font='700 29px Segoe UI';wrap(data.brief||data.reading.verdict,125,y+87,830,40,2);y+=205;c.fillStyle='#a83b2e';c.font='700 21px Segoe UI';c.fillText('CLOSING INTERPRETATION',100,y);c.fillStyle='#40362e';c.font='28px Georgia';y=wrap('Full interpretation available at lfun.cloud.',100,y+55,880,43,8)+35;c.fillStyle='#6e5c4c';c.font='23px Segoe UI';wrap(CATEGORY_NAMES[data.record.category],100,y,880,35,3);c.fillStyle='#806f60';c.font='20px Segoe UI';c.fillText('Traditional cultural experience · lfun.cloud/en/',100,1250);const a=document.createElement('a');a.href=canvas.toDataURL('image/png');a.download=`wenshi-${PALACES[data.p.t][0].toLowerCase().replace(' ','-')}.png`;a.click()}
function updateHint(){const q=$('question').value.trim();if(!q){$('autoHint').textContent='Type your question to see the detected category.';$('clarifyBox').hidden=true;return}const c=classify(q,$('category').value);$('autoHint').innerHTML=`Detected: <b>${CATEGORY_NAMES[c]}</b>`;$('clarifyBox').hidden=false;$('clarifyPrompt').textContent=CLARIFY[c]}
function render(record){
const cal=lunar(new Date(record.iso)),p=calculate(cal),hour=PALACES[p.t],month=PALACES[p.m],day=PALACES[p.d],brief=hour[2];
lastReading={record:record,p:p,cal:cal,brief:brief,reading:{verdict:brief,focus:'',transition:'',closing:''}};
$('empty').hidden=true;
$('result').hidden=false;
$('resultTag').textContent=`${CATEGORY_NAMES[record.category]} · ${hour[0]}`;
let caution='';
if(/cancer|illness|disease|pregnan|medicine|medication|surgery|suicide|self-harm|death|stock|fund|invest|lottery|gambl|lawsuit|prosecut|litigation/i.test(record.question+' '+(record.details||'')))caution='<p class="caution">This touches health, safety, money or the law. A reading cannot determine the outcome — rely on real evidence and qualified professional help.</p>';
$('result').innerHTML=`<div class="en-result-head"><div class="en-palace">${hour[0]}</div><div><h2>${hour[1]}</h2><p>${cal.solar} CST · Lunar ${cal.leap?'leap ':''}month ${cal.month}, day ${cal.day}</p></div></div><p class="asked">Asked: ${escapeHtml(record.question)}${record.details?`<small>Context: ${escapeHtml(record.details)}</small>`:''}</p><section class="en-card"><small>DIRECT ANSWER</small><h3>${escapeHtml(brief)}</h3><p>${escapeHtml(CATEGORY_NAMES[record.category])} · ${hour[0]} — ${hour[1]}</p></section><section class="en-card"><small>HOW IT WAS CALCULATED</small><p><b>1 · Month:</b> Lunar month ${cal.month} counts from Da An and lands on ${month[0]} — ${month[2]}</p><p><b>2 · Day:</b> Lunar day ${cal.day} counts from ${month[0]} and lands on ${day[0]} — ${day[2]}</p><p><b>3 · Hour:</b> The current two-hour period counts from ${day[0]} and lands on ${hour[0]} — ${hour[2]}</p><p>The full interpretation is delivered by the server after unlock.</p></section>${caution}<div class="en-share"><button id="copyResult">Copy reading</button><button id="shareResult" class="secondary">Share</button></div>`;
const text=`Wenshi · Xiao Liu Ren\nQuestion: ${record.question}\nResult: ${hour[0]} — ${brief}\n\nTraditional cultural experience only.`;
$('copyResult').addEventListener('click',async e=>{await navigator.clipboard.writeText(text);e.currentTarget.textContent='Copied'});
$('shareResult').addEventListener('click',async()=>{if(navigator.share)await navigator.share({title:'Wenshi · Xiao Liu Ren',text});else await navigator.clipboard.writeText(text)});
$('result').scrollIntoView({behavior:'smooth',block:'start'});
}
$('question').addEventListener('input',()=>{$('counter').textContent=`${$('question').value.length} / 300`;updateHint()});$('category').addEventListener('change',updateHint);$('questionForm').addEventListener('submit',e=>{e.preventDefault();const question=$('question').value.trim(),details=$('details').value.trim();if(question.length<3){$('error').textContent='Please write a more specific question.';return}$('error').textContent='';render({question,details,iso:new Date().toISOString(),category:classify(question+' '+details,$('category').value)})});function tick(){const c=lunar(new Date());$('clock').textContent=c.solar;$('lunarClock').textContent=`Lunar ${c.leap?'leap ':''}month ${c.month}, day ${c.day}`};tick();setInterval(tick,1000);$('aboutOpen').addEventListener('click',()=>$('about').showModal());$('aboutClose').addEventListener('click',()=>$('about').close());$('noticeOpen').addEventListener('click',()=>$('notice').showModal());$('noticeClose').addEventListener('click',()=>$('notice').close());
new MutationObserver(()=>{const tools=$('result').querySelector('.en-share');if(!tools||tools.querySelector('#downloadCard'))return;const button=document.createElement('button');button.id='downloadCard';button.className='secondary';button.textContent='Download share card';button.addEventListener('click',()=>lastReading&&downloadCard(lastReading));tools.append(button)}).observe($('result'),{childList:true,subtree:true});
